"""A shopping cart: lines of a product, a unit price and a quantity."""

from decimal import Decimal


class Line:
    def __init__(self, sku, price, quantity=1):
        if quantity < 1:
            raise ValueError("quantity must be 1 or more")
        self.sku = sku
        self.price = Decimal(price)
        self.quantity = quantity

    def subtotal(self):
        return self.price * self.quantity


class Cart:
    def __init__(self):
        self.lines = {}

    def add(self, sku, price, quantity=1):
        line = self.lines.get(sku)
        if line:
            line.quantity += quantity
        else:
            self.lines[sku] = Line(sku, price, quantity)

    def remove(self, sku, quantity=1):
        line = self.lines[sku]
        line.quantity -= quantity
        if line.quantity <= 0:
            del self.lines[sku]

    def count(self):
        return sum(line.quantity for line in self.lines.values())

    def total(self):
        return sum((line.subtotal() for line in self.lines.values()), Decimal("0"))
